import csv, json, collections

merchant = "Belles_cookbook_store"
target_year = 2023
target_doy = 10

with open("merchant_data.json") as f:
    merchants = json.load(f)
m = next(x for x in merchants if x["merchant"] == merchant)

acq_country = {}
with open("acquirer_countries.csv", newline="") as f:
    for row in csv.DictReader(f):
        acq_country[row["acquirer"]] = row["country_code"]
merch_acq_country = acq_country[m["acquirer"][0]]

# January 2023 stats
jan_rows = []
day10_rows = []
with open("payments.csv", newline="") as f:
    for row in csv.DictReader(f):
        if row["merchant"] != merchant or int(row["year"]) != target_year:
            continue
        doy = int(row["day_of_year"])
        if doy <= 31:
            jan_rows.append(row)
        if doy == target_doy:
            day10_rows.append(row)

total_vol = sum(float(r["eur_amount"]) for r in jan_rows)
fraud_vol = sum(float(r["eur_amount"]) for r in jan_rows if r["has_fraudulent_dispute"] == "True")
fraud_pct = fraud_vol / total_vol * 100

# Determine monthly_volume bucket
if total_vol < 100_000:
    vol_bucket = "<100k"
elif total_vol < 1_000_000:
    vol_bucket = "100k-1m"
elif total_vol < 5_000_000:
    vol_bucket = "1m-5m"
else:
    vol_bucket = ">5m"

# Determine monthly_fraud_level bucket
if fraud_pct < 7.2:
    fraud_bucket = "<7.2%"
elif fraud_pct < 7.7:
    fraud_bucket = "7.2%-7.7%"
elif fraud_pct <= 8.3:
    fraud_bucket = "7.7%-8.3%"
else:
    fraud_bucket = ">8.3%"

# capture_delay: merchant value "1" -> "<3"
cd = m["capture_delay"]
if cd in ("immediate", "manual"):
    cd_bucket = cd
else:
    d = int(cd)
    cd_bucket = "<3" if d < 3 else ("3-5" if d <= 5 else ">5")

print("vol_bucket:", vol_bucket, "fraud_bucket:", fraud_bucket, "capture_delay:", cd_bucket)
print("acquirer country:", merch_acq_country, "account_type:", m["account_type"], "mcc:", m["merchant_category_code"])

with open("fees.json") as f:
    fees = json.load(f)

def matches(fee, tx):
    if fee["card_scheme"] is not None and fee["card_scheme"] != tx["card_scheme"]:
        return False
    at = fee["account_type"]
    if at and m["account_type"] not in at:
        return False
    if fee["capture_delay"] is not None and fee["capture_delay"] != cd_bucket:
        return False
    if fee["monthly_fraud_level"] is not None and fee["monthly_fraud_level"] != fraud_bucket:
        return False
    if fee["monthly_volume"] is not None and fee["monthly_volume"] != vol_bucket:
        return False
    mcc = fee["merchant_category_code"]
    if mcc and m["merchant_category_code"] not in mcc:
        return False
    if fee["is_credit"] is not None and fee["is_credit"] != (tx["is_credit"] == "True"):
        return False
    aci = fee["aci"]
    if aci and tx["aci"] not in aci:
        return False
    if fee["intracountry"] is not None:
        intra = (tx["issuing_country"] == tx["acquirer_country"])
        if bool(fee["intracountry"]) != intra:
            return False
    return True

applicable = set()
